"%% model.m — Robust stability margins of a cascaded (inner + outer) loop
%
% INNER loop : G_in(s) = 1/(s*(s+4)),  feedback gain ki = 12 (unity negative fb)
%              G_in_cl(s) = ki*G_in / (1 + ki*G_in)
% OUTER loop : G_out(s) = 2.5/(s*(s+2))
% TOTAL open loop (inner closed first, then cascaded):
%              L(s) = G_out(s) * G_in_cl(s)
%
% Compute gain & phase margins of L(s) and write result.json.

clear; clc;

s = tf('s');

% ---- Inner loop (closed first) ----
ki      = 12.0;
G_in    = 1 / (s * (s + 4.0));
G_in_cl = feedback(ki * G_in, 1);          % close INNER loop

% ---- Outer loop plant ----
G_out = 2.5 / (s * (s + 2.0));

% ---- Cascaded total open loop ----
L = G_out * G_in_cl;

% ---- Margins of the total open loop ----
[gm_lin, pm, w_pc, w_gc] = margin(L);

% Guard: take scalars (single gain & phase crossover for this system)
gm_lin = double(gm_lin(1));
pm     = double(pm(1));
w_pc   = double(w_pc(1));
w_gc   = double(w_gc(1));

% ---- Assemble result struct ----
result = struct();
result.gm_db  = 20 * log10(gm_lin);   % gain margin in dB
result.pm_deg = pm;                   % phase margin in degrees
result.w_gc   = w_gc;                 % gain crossover frequency (rad/s)
result.w_pc   = w_pc;                 % phase crossover frequency (rad/s)

% ---- Write result.json ----
txt = jsonencode(result);
fid = fopen('result.json', 'w');
if fid < 0
    error('Failed to open result.json for writing.');
end
fprintf(fid, '%s', txt);
fclose(fid);

fprintf('gm_db  = %.6f dB\n',   result.gm_db);
fprintf('pm_deg = %.6f deg\n',  result.pm_deg);
fprintf('w_gc   = %.6f rad/s\n', result.w_gc);
fprintf('w_pc   = %.6f rad/s\n', result.w_pc);"
